DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261031071702_AgregarOrigenMovimientoCuenta') THEN
    ALTER TABLE "MovimientosCuentaCorriente" ADD "Origen" integer;
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261031071702_AgregarOrigenMovimientoCuenta') THEN
    UPDATE "MovimientosCuentaCorriente"
    SET "Origen" = CASE
        -- Movimientos correspondientes a pagos.
        WHEN "Tipo" = 2
            AND "PagoId" IS NOT NULL
            THEN 2

        -- Anulaciones de ventas.
        WHEN "Tipo" = 2
            AND "VentaId" IS NOT NULL
            AND "PagoId" IS NULL
            AND "Descripcion" LIKE 'Anulación de venta #%'
            THEN 3

        -- Débitos generados por ventas.
        WHEN "Tipo" = 1
            AND "VentaId" IS NOT NULL
            AND "PagoId" IS NULL
            THEN 1

        -- Movimientos manuales sin relaciones.
        WHEN "VentaId" IS NULL
            AND "PagoId" IS NULL
            THEN 6

        ELSE NULL
    END;
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261031071702_AgregarOrigenMovimientoCuenta') THEN
    DO $$
    BEGIN
        IF EXISTS (
            SELECT 1
            FROM "MovimientosCuentaCorriente"
            WHERE "Origen" IS NULL
        ) THEN
            RAISE EXCEPTION
                'Existen movimientos históricos sin origen identificado.';
        END IF;
    END $$;
    END IF;
END $EF$;

